P=timerange('1996-01-01','2026-01-01');
JFJ_tr=JFJ_tr(P,:);
%%

%no MAAP used
%JFJ_tr.BaR=[];
%abs since 2002

%AE since 2002
pA=timerange('1996-01-01','2002-01-01');
names=fieldnames(JFJ_tr);
c= startsWith(names,["Ba"]) ;
N=names(c);
for i=1:length(N)
    JFJ_tr.(N{i})(pA)=NaN;
end

% MAAP only since 2004
pMaap=timerange('1996-01-01','2004-01-01');
JFJ_tr.BaR_A(pMaap)=NaN;

% remove non used variables

c= endsWith(names,["ae31","ae33","B_S","R_S"]) ;
N=names(c);
for i=1:length(N)
    JFJ_tr.(N{i})=[];
end

% use expS onlysince 2015
p1=timerange('1996-01-01','2015-01-01');
JFJ_tr.BbsFg(p1)=NaN;
JFJ_tr.expS_bg(p1)=NaN;

JFJ_tr.expS_br=[];
JFJ_tr.expS_gr=[];

JFJ_tr.BbsFb=[];
JFJ_tr.BbsFr=[];

%use only green + test trend on red due to problem before reparation
JFJ_tr.expA_bgAE=[];
JFJ_tr.expA_brAE=[];
JFJ_tr.expA_grAE=[];

% use ExpA_fit only until 2021 due to tape change thereafter
p2=timerange('2022-01-01','2026-01-01');
JFJ_tr.expA_fit(p2)=NaN;


JFJ_tr.Ba1_Ah=[];
JFJ_tr.Ba2_Ah=[];
JFJ_tr.Ba4_Ah=[];
JFJ_tr.Ba5_Ah=[];
JFJ_tr.Ba6_Ah=[];
JFJ_tr.Ba7_Ah=[];
%%
% data should be in Mm1
names=fieldnames(JFJ_tr);
names_var=names(startsWith(names,'B'));
for i=1:length(names_var)
    JFJ_tr.(names_var{i})=JFJ_tr.(names_var{i}).*1e6;
end
